#!/bin/bash

# =======================================================
# R36H Pro Max dArkOS Fullscreen Files Viewer
# by djparent
# =======================================================

# -------------------------------------------------------
# Root privileges check
# -------------------------------------------------------
if [ "$(id -u)" -ne 0 ]; then
    exec sudo -- "$0" "$@"
fi

# -------------------------------------------------------
# Initialization
# -------------------------------------------------------
clear
echo "========================================================="
echo "     R36H Pro Max dArkOSen Fullscreen Files Viewer"
echo "                     by djparent"
echo "========================================================="
echo "Starting..."
sleep 0.5

# -------------------------------------------------------
# Variables
# -------------------------------------------------------
FILES_B64=""
ZIP="/tmp/Files.zip"
FILES="/opt/dingux"

# -------------------------------------------------------
# Decode and unpack ZIP
# -------------------------------------------------------
echo "Replacing Files viewer with fullscreen version..."
[[ ! -d "$FILES.old" ]] && cp -r "$FILES" "$FILES.old"

printf '%s' "$FILES_B64" | base64 -d > "$ZIP"

echo "Unpacking..."
unzip -oq "$ZIP" -d /opt

echo "Granting permissions..."
chmod -R +x "$FILES"
chown -R ark:ark "$FILES"

echo "Done."
sleep 2